/**
 * Recovery terms for a lease - stored as JSONB in the leases table.
 *
 * This is the 'Financial DNA' extracted from lease documents containing
 * all terms needed to calculate tenant expense recoveries.
 */
export type LeaseRecoveryProfile_Input = {
  /**
   * Base year for expense stop calculation
   */
  base_year?: number | null
  /**
   * Frozen base year expense amount (if pre-calculated)
   */
  base_year_amount?: number | string | null
  /**
   * Whether to gross-up base year if occupancy < 95%
   */
  gross_up_base_year?: boolean
  /**
   * Tenant's percentage share (e.g., 0.05 for 5%)
   */
  pro_rata_share: number | string
  /**
   * Type of cap applied to recoveries
   */
  cap_type?: CapType
  /**
   * Cap rate as decimal (e.g., 0.05 for 5%)
   */
  cap_rate?: number | string | null
  /**
   * Admin fee as decimal (e.g., 0.15 for 15%)
   */
  admin_fee_percentage?: number | string
  /**
   * Expense pools excluded from this tenant's recovery
   */
  excluded_pools?: Array<PoolType>
  /**
   * BOMA standard used to derive this tenant's pro_rata_share
   */
  rsf_measurement_standard?: BomaStandardVersion | null
  /**
   * Date the tenant's RSF was certified for pro-rata calculation
   */
  rsf_measurement_date?: string | null
  /**
   * Cash or accrual basis for GL date filtering. Null defaults to cash with warning.
   */
  accounting_basis?: AccountingBasis | null
  /**
   * Imputed costs for services introduced after the base year; added to base_year_amount before computing the increase
   */
  base_year_adjustments?: Array<BaseYearAdjustmentItem_Input>
}

